import {createReplacementReview} from '../functional-home/replacement-review.js';
import {toolRepairPorts,gearSwapPorts} from './adapters.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mounted=false;
function mount(){if(mounted||!window.simulationTestHooks?.saveStatus().ownsSave)return;mounted=true;
 const p=window.equipmentComparisonPorts,root=document.createElement('section');root.id='functional_home';root.className='equipment-comparison';root.setAttribute('aria-label','Equipment comparison workbench');
 root.innerHTML='<div class="fh-header"><h2>Repair or replace · native equipment</h2><button type="button" data-current="tools">Current Tools</button><button type="button" data-current="gear-workshop">Current Gear workshop</button></div><p class="fh-meta">Prepared disposable midgame stock · real native quotes and commitments · manual clock in workbench toolbar.</p><div class="fh-grid"><div data-tool-review></div><div><section class="fh-section"><h3>Choose gear and operator</h3><label>Carried gear <select aria-label="Compare carried gear" data-gear-choice></select></label><label>Component <select aria-label="Compare gear slot" data-slot-choice></select></label><label>Maker <select aria-label="Compare gear maker" data-maker-choice></select></label></section><div data-gear-review></div></div></div><section class="fh-section" data-repair-job aria-live="polite"></section><p role="status" data-comparison-status></p>';
 const home=document.getElementById('gear_workshop');home.before(root);let item='',slot='head',maker='player',sig='';
 const select=(s,rows,value)=>{const n=root.querySelector(s);if(JSON.stringify(rows)!==n.dataset.rows){n.innerHTML=rows.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');n.dataset.rows=JSON.stringify(rows);}n.value=value;};
 const tools=createReplacementReview({...toolRepairPorts(p),escape:esc}),gear=createReplacementReview({...gearSwapPorts(p,{selectedItem:()=>item,selectedSlot:()=>slot,selectedMaker:()=>maker,onResult:key=>{item=key;sig='';render();}}),escape:esc});root.querySelector('[data-tool-review]').append(tools.node);root.querySelector('[data-gear-review]').append(gear.node);
 function open(id){home.hidden=false;const s=document.querySelector('#workspace_navigation select');s.value=id;s.dispatchEvent(new Event('change',{bubbles:true}));window.equipmentComparisonPorts.openPanel(id);root.hidden=true;}
 function show(){open('gear-workshop');home.before(root);home.hidden=true;root.hidden=false;root.scrollIntoView({block:'start'});render();}
 function render(){const v=p.gear(),t=p.tools(),identity=JSON.stringify([v,t,item,slot,maker]);if(identity===sig)return;sig=identity;if(!v.rows.some(r=>r.key===item))item=v.rows[0]?.key||'';const row=v.rows.find(r=>r.key===item);if(!row?.components[slot])slot=Object.keys(row?.components||{})[0]||'';select('[data-gear-choice]',v.rows.map(r=>[r.key,r.name]),item);select('[data-slot-choice]',Object.entries(row?.components||{}).map(([k,val])=>[k,k+' · '+val]),slot);select('[data-maker-choice]',v.makers.map(r=>[r.id,r.name]),maker);tools.update();gear.update();const job=root.querySelector('[data-repair-job]');job.innerHTML=t.job?`<h3>Active repair · ${esc(t.job.name)}</h3><p>${t.job.minutesLeft} / ${t.job.total} minutes remain · ${t.location!==t.job.location?'paused: away from repair place':!t.idle?'paused: another activity':esc(t.repairBlocked||'supported idle work')}</p><p>Reserved: ${esc(t.job.spent.map(r=>r.count+' '+r.id).join(', ')||'no materials')}</p><button type="button" data-cancel-repair>Cancel repair · return reserved materials</button>`:'<h3>Repair status</h3><p>No repair job. Final outcomes appear in native Reports and tool condition.</p>';}
 root.addEventListener('change',e=>{if(e.target.hasAttribute('data-gear-choice'))item=e.target.value;else if(e.target.hasAttribute('data-slot-choice'))slot=e.target.value;else if(e.target.hasAttribute('data-maker-choice'))maker=e.target.value;else return;sig='';render();});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.current)open(b.dataset.current);if(b?.hasAttribute('data-cancel-repair')){try{p.cancelRepair();root.querySelector('[data-comparison-status]').textContent='Repair cancelled through native owner; reserved materials returned.';}catch(e){root.querySelector('[data-comparison-status]').textContent=e.message;}sig='';render();}});
 const back=document.createElement('button');back.type='button';back.textContent='Equipment comparison';back.onclick=show;document.getElementById('workspace_pane_navigation').append(back);
 window.addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='mockup:command')return;const{id,command,value}=e.data;try{if(command==='text'){for(const n of[root]){n.style.setProperty('--ui-type-body',Number(value)+'px');n.style.setProperty('--ui-type-small',Math.max(12,value-2)+'px');}document.documentElement.style.setProperty('--ui-type-body',value+'px');}if(command==='step'){window.advanceTicks(1);sig='';render();}if(command==='variant'){if(value==='current')open('gear-workshop');else show();}parent.postMessage({type:'mockup:reply',id,snapshot:{route:'equipment-comparison'}},location.origin);}catch(error){parent.postMessage({type:'mockup:reply',id,error:error.message},location.origin);}});
 // Native owners publish their normal UI changes; this timer reads only, never advances work/time.
 setInterval(()=>{if(window.simulationTestHooks.saveStatus().ownsSave)render();},250);show();parent.postMessage({type:'mockup:ready'},location.origin);
}
window.addEventListener('equipment-comparison-ready',mount);
